fn bump(n: *int) {
  n.* = n.* + 1
}

fn main() {
  let x = 1
  bump(x.&)
  bump(x.&)
  println(x)

  let boxed: *int = mem/new(41)
  bump(boxed)
  println(boxed.*)
}

fn fib(n: int): int {
  if n < 2 n else fib(n - 1) + fib(n - 2)
}

let ANSWER: int = fib(30) * fib(20) + 1

